export const ACADEMY_CONTENT = Object.freeze({"locale":"zh-Hans","lessons":[{"ep":1,"title":"一枚比特币太贵，我就不能买吗？","goal":"能区分币的数量与购买金额，知道比特币可拆分购买。","task":"试着算一算：价格为 50,000 USDT 时，花 100 USDT 能买到多少 BTC？只在模拟页面计算，不创建真实订单。","answer":"0.002 BTC，计算未扣手续费。","takeaways":["一枚比特币的价格，不等于入门的门槛。","比特币可以按小数买：价格 50,000 时花 100，就是 0.002 BTC。","各平台的最小下单金额和手续费不同，先看清这两项。"],"quiz":{"q":"一枚比特币 50,000 USDT，你花 100 USDT（不计手续费），能买到多少？","options":["买不了，必须买一整枚","0.002 BTC","0.02 BTC"],"answer":1,"why":"100 ÷ 50,000 = 0.002。比特币可以只持有一小部分。"},"transcript":[{"t":0.25,"who":"sam","text":"一枚这么贵，我的钱是不是连门票都买不起？"},{"t":9.25,"who":"nexubo","text":"你看到的是一整枚的价格，不是每次必须支付的金额。比特币是一种数字资产，可以按小数数量持有，通常不用一次买一整枚。"},{"t":25.25,"who":"narrator","text":"只做一道假设题：一枚值50,000单位泰达币，成交金额是100，忽略费用，就对应0.002枚比特币。这不是今天的市场报价。"},{"t":45.25,"who":"sam","text":"那价格涨跌时呢？"},{"t":47,"who":"nexubo","text":"你持有的数量可以不变，折合价值却会涨，也会跌。买得少，只是投入少，不等于没有风险。"},{"t":62.25,"who":"nexubo","text":"能拆分，不代表所有平台都接受任意小的订单。还要检查最小金额和费用。学习阶段先用虚拟资金，不需要充值。"},{"t":75.25,"who":"narrator","text":"购买比特币必须买一整枚吗？不必。记住：整枚的价格，不是入门的门槛。"},{"t":86.25,"who":"narrator","text":"大多数交易都用USDT标价。可它真的是美元吗？下一集揭晓。"},{"t":92.55,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":2,"title":"USDT是美元吗？为什么买币常见它？","goal":"理解稳定币的用途、目标锚定及风险，知道买币不必先买USDT。","task":"把\"美元存款\"\"USDT\"\"BTC\"放进正确类别。","answer":"USDT属于加密资产中的稳定币，不是银行美元存款。","takeaways":["USDT 是稳定币，设计目标是接近一美元，但不是银行存款。","交易所常用它来计价和兑换，所以卖出后往往拿到的是 USDT。","“稳定”是设计目标而非保证：价格会偏离，赎回也有条件。"],"quiz":{"q":"关于 USDT，哪一句是对的？","options":["它就是你银行账户里的美元","它是稳定币，属于一种加密资产","它永远不会偏离 1 美元"],"answer":1,"why":"USDT 追踪美元，但它是加密资产，有自己的发行方风险和平台风险。"},"transcript":[{"t":0.25,"who":"sam","text":"这个叫泰达币，所以它就是美元存款？"},{"t":9.25,"who":"nexubo","text":"不是。泰达币是一种稳定币，设计目标是尽量贴近一美元，但它不是你银行账户里的美元，也不是没有风险的现金。"},{"t":25.25,"who":"narrator","text":"交易里常用它作为报价和交换的资产。比如你用泰达币买比特币，卖出后也可能收到泰达币，而不是直接收到银行转账。"},{"t":45.25,"who":"nexubo","text":"所谓稳定，是设计目标，不是绝对保证。价格可能偏离，发行与赎回也有条件；持有时仍要了解发行方和平台风险。"},{"t":62.25,"who":"sam","text":"所以买币必须先买泰达币？"},{"t":65.23,"who":"nexubo","text":"也不一定。支持哪些法币和交易对，要看你所在地区与平台提供的服务。"},{"t":75.25,"who":"narrator","text":"这句话错在哪里？稳定币不是保本承诺；理解用途，也要理解它可能不稳定。"},{"t":86.25,"who":"narrator","text":"如果今晚手机摔坏，你的币也会没吗？下一集：币到底在哪。"},{"t":92.15,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":3,"title":"币到底在哪：交易所和钱包有什么不同？","goal":"能区分托管交易账户与自托管钱包，理解控制权与恢复责任。","task":"匹配两个场景：交易所登录账户；普通助记词自托管钱包。","answer":"两者控制权和恢复机制不同；自托管不等于自动安全。","takeaways":["交易所账户里，资产和密钥主要由平台托管。","自托管钱包由你掌握凭证，找回的责任也在你自己。","先问清“谁有权限转走资产”，再决定用哪种方式。"],"quiz":{"q":"标准助记词自托管钱包，你弄丢了助记词，也没有其他找回方式，会怎样？","options":["客服可以帮你重置","可能永久失去访问权","交易所会自动恢复"],"answer":1,"why":"自托管意味着密钥在你手里。没有助记词或其他有效方式，谁也无法替你找回。"},"transcript":[{"t":0.25,"who":"sam","text":"手机坏了，币是不是也一起摔没了？"},{"t":9.25,"who":"nexubo","text":"不是把硬币装进手机。钱包帮你查看链上资产，并用密钥授权操作。能否恢复，取决于你用什么钱包、保留了哪些恢复方式。"},{"t":32.25,"who":"narrator","text":"交易所托管账户主要由平台管理底层资产与密钥，你用账户操作。自托管钱包则由你负责控制凭证；使用方便与责任分配不同。"},{"t":60.25,"who":"sam","text":"两边忘记密码都找客服？"},{"t":63.86,"who":"nexubo","text":"不能这样想。普通助记词钱包的恢复凭证丢失，且没有其他有效恢复方式时，客服无法替你找回。"},{"t":84.25,"who":"nexubo","text":"放在平台有平台风险，自己保管也会因泄露密钥或错误授权损失。今天只理解区别，不要求你立刻搬走所有资产。"},{"t":103.25,"who":"narrator","text":"谁在控制资产的操作权限？先回答这件事，再决定你需要哪种账户或钱包。"},{"t":116.25,"who":"narrator","text":"两扇门一模一样，其中一扇是假的。下一集：怎么认出真门。"},{"t":121.75,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":4,"title":"先认门，再注册：别把账户开在假平台","goal":"知道先查地区资格、官方入口与费用，再注册并启用安全设置。","task":"在虚拟平台资料卡里找出地区不支持、入口异常和未披露费用。","answer":"任一关键资格或入口问题未解决，都不应继续。","takeaways":["第一步先确认平台是否服务你真实所在的国家或地区。","只通过确认过的官方入口注册，用你自己的邮箱或手机号。","注册完立刻开启安全设置，保存好找回方式。"],"quiz":{"q":"注册之前，最先要确认的是什么？","options":["新人奖励有多大","平台是否服务你所在地区、入口是否官方","平台有多少粉丝"],"answer":1,"why":"资格和官方入口排在最前面。奖励不应该决定你在哪里开户。"},"transcript":[{"t":0.25,"who":"sam","text":"这个奖励特别高，我就从这扇门进去？"},{"t":9.25,"who":"nexubo","text":"先别被奖励决定。先查当地是否允许、平台是否接受你的真实居住地区、由哪个主体提供服务，再看费用、入金和提现条件。"},{"t":32.25,"who":"narrator","text":"确认官方入口后，再用自己的邮箱或手机号注册，设置独立密码，完成页面要求的验证。不要购买别人的账户，也不要虚构身份和地区。"},{"t":60.25,"who":"nexubo","text":"注册不是最后一步。把平台支持的安全措施设置好，检查登录设备，保存恢复方式。一次性验证码也不能发给所谓的客服代办。"},{"t":84.25,"who":"narrator","text":"我们的网站可以帮助你查信息，但推广关系不等于安全担保。资料未确认时，先不进入开户流程。"},{"t":103.25,"who":"sam","text":"停止，先确认资格和规则。"},{"t":107.02,"who":"nexubo","text":"对。先认门，再开户。"},{"t":116.25,"who":"nexubo","text":"想要一扇可信的门？NexuAlpha 列出每家交易所核验过的官方入口。我们的 OKX 合作链接直达官网，填写邀请码 nexu888 还能享受手续费返还。"},{"t":127.35,"who":"narrator","text":"现在就做：打开两步验证。然后回来——下一集，有人在聊天里说能替你代办认证。"},{"t":134.45,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":5,"title":"KYC怎么做？证件应该交给谁？","goal":"理解身份认证的一般目的和流程，知道只向核验后的官方渠道提交。","task":"用虚构信息排列认证步骤；课程禁止上传真实证件。","answer":"核验入口→按本地区要求提交真实本人资料→等待并核对结果。","takeaways":["KYC 用来确认你是账户本人，并帮助平台满足合规要求。","证件只在官方认证流程里提交，绝不发到聊天里。","认证失败先看原因，按提示补正，用真实身份重试。"],"quiz":{"q":"你的证件应该交给谁？","options":["聊天群里热心的“代办”","只交给核验过的官方认证流程","发到课程聊天区让大家帮看"],"answer":1,"why":"只走官方流程。NexuAlpha 从不索取你的证件，陌生人更不应该。"},"transcript":[{"t":0.25,"who":"sam","text":"它要我的证件，旁边这个人说能帮我代办？"},{"t":9.25,"who":"nexubo","text":"身份认证通常用来核实账户本人、满足合规要求。先确认是官方流程，不要把证件、验证码交给聊天群里的代办。"},{"t":32.25,"who":"narrator","text":"一般先填真实信息，再提交支持的有效证件，按提示完成照片或本人验证。是否需要地址证明、接受什么证件，都取决于地区和平台。"},{"t":60.25,"who":"nexubo","text":"失败时先看原因：证件是否过期、画面是否反光、姓名是否一致。按提示补正，不要换一个虚假的身份去尝试。"},{"t":84.25,"who":"sam","text":"做完是不是马上能交易？"},{"t":86.78,"who":"nexubo","text":"不保证。审核结果、可用产品和入金资格都要看官方通知。这个学院也不收集你的真实证件。"},{"t":103.25,"who":"narrator","text":"证件交给谁？只按核验后的官方流程提交，不交给我们，也不交给陌生人。"},{"t":116.25,"who":"nexubo","text":"准备好认证了？只在官网开始。我们的 OKX 合作链接直达官网，邀请码 nexu888 可享手续费返还。我们从不索取你的证件。"},{"t":127.25,"who":"narrator","text":"充值、买币、划转，三个按钮长得都像。下一集：到底该按哪个。"},{"t":132.85,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":6,"title":"第一次入金：钱从哪里来，进到哪里去？","goal":"能区分法币入金、买币、链上充值与账户内部划转。","task":"将三种资金来源匹配到法币入金、链上充值和内部划转。","answer":"银行法币与链上代币地址不能混用；每条通道独立核验。","takeaways":["法币入金、买币、链上充值、内部划转，是四条不同的路。","链上充值要选平台支持的币种和网络；内部划转只在平台内部移动。","绝不私下向陌生人付款；先确认余额会到哪个账户。"],"quiz":{"q":"你在同一平台把 USDT 从资金账户转到交易账户，这属于什么？","options":["链上充值","内部划转","法币入金"],"answer":1,"why":"它只是在你自己的账户之间移动余额，通常不是链上转账。"},"transcript":[{"t":0.25,"who":"sam","text":"这些都像把钱转进去，我到底该按哪个？"},{"t":9.25,"who":"nexubo","text":"先看你手里是什么。银行里的法币、其他地方已有的币、平台里另一个账户的余额，需要走的路不一样。"},{"t":32.25,"who":"narrator","text":"法币充值通常是给账户增加法币余额；直接买币则是付款后获得加密资产。有的平台支持银行或银行卡渠道，有的不支持，费用和限制也不同。"},{"t":60.25,"who":"nexubo","text":"已有加密资产，可以按支持的币种和网络充值。平台内部划转是账户间调配余额，通常不是链上转账。先确认余额会到哪里。"},{"t":84.25,"who":"narrator","text":"有的平台还提供用户间交易，但不是银行转账的同义词。不要私下脱离平台付款，不使用来路不明或第三方代付资金；没看懂就先不操作。"},{"t":103.25,"who":"sam","text":"不能，这是不同通道。"},{"t":105.59,"who":"nexubo","text":"对，先看资产，再看路径，最后核对实际到账。"},{"t":116.25,"who":"narrator","text":"BTC/USDT中间这道斜杠，是要买两种币吗？下一集：第一笔现货。"},{"t":122.45,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":7,"title":"第一笔现货交易：用 100 USDT 买到 0.002 枚 BTC","goal":"完成一笔明确金额、数量和费用的模拟现货买入。","task":"用 1,000 USDT 虚拟资金买入 0.002 BTC，核对剩余 USDT 余额 899.90 及成交记录。","answer":"成交金额100，费用0.10，总支出100.10；余899.90。","takeaways":["BTC/USDT 表示比特币用 USDT 计价：付 USDT，得到比特币。","下单前看清输入框要的是金额还是币的数量。","买完查看成交记录：成交状态、成交均价和手续费。"],"quiz":{"q":"按 50,000 买入 0.002 BTC，另收 0.1% 的 USDT 手续费，一共花多少？","options":["100","100.10","110"],"answer":1,"why":"买币 100，加手续费 0.10，合计 100.10。"},"transcript":[{"t":0.25,"who":"sam","text":"这个斜杠，是让我同时买两种币吗？"},{"t":9.25,"who":"nexubo","text":"不是。这表示用泰达币来给比特币报价。买入时，你付出报价资产，获得比特币；卖出时方向相反。"},{"t":35.25,"who":"narrator","text":"我们用虚拟账户练习。确认是现货，不是合约；选择交易对、买入方向，再输入成交金额。提交前看清它要求填金额，还是币的数量。"},{"t":67.25,"who":"nexubo","text":"假设成交价是50,000，成交金额100，就买到0.002枚。再假设手续费0.1%、从报价余额另扣，你总共支出100.10。真实规则以平台为准。"},{"t":95.25,"who":"sam","text":"按了买入就一定有币了？"},{"t":99.07,"who":"nexubo","text":"还要查成交记录。未成交、部分成交和全部成交不同；实际均价和费用也要核对。"},{"t":116.25,"who":"narrator","text":"第一笔练习不是猜涨跌，而是把这五项核对清楚。完成后，你也可以选择暂时不做真实交易。"},{"t":131.25,"who":"nexubo","text":"等你准备好做真实的第一笔交易，可以通过我们的 Bitget 合作链接注册，邀请码 nexu888 可返还部分交易手续费。每一次都做同样的五项核对。"},{"t":140.95,"who":"narrator","text":"假如涨了你卖出，为什么银行卡余额还是没动？下一集讲。"},{"t":146.85,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":8,"title":"卖出以后，钱为什么没到银行卡？","goal":"区分卖出资产、获得稳定币或法币余额，以及实际银行提现。","task":"完成模拟卖出，并在资产流向图中标明哪一步才是银行提现。","answer":"卖出到USDT不等于银行提现；本例净交易盈亏9.79。","takeaways":["卖成 USDT，得到的是 USDT 余额，不是银行卡里的钱。","卖出和提现到银行卡是两个独立的步骤。","价格上涨不等于净收益：先把各项费用扣掉。"],"quiz":{"q":"你把比特币卖成了 USDT，钱现在在哪？","options":["在你的银行卡里","作为 USDT 余额留在平台上","已经自动换成本地货币"],"answer":1,"why":"你收到的是 USDT。把钱转回银行卡是另一个提现步骤。"},"transcript":[{"t":0.25,"who":"sam","text":"我明明卖了，银行卡怎么还没收到钱？"},{"t":9.25,"who":"nexubo","text":"先看你卖给了哪个交易对。如果卖成泰达币，得到的是泰达币余额，不是银行到账。卖出和法币提现，是两个步骤。"},{"t":35.25,"who":"narrator","text":"沿用教学例子，0.002枚按55,000卖出，成交金额110；扣假设费用0.11，到账109.89。"},{"t":67.25,"who":"sam","text":"那我赚了十？"},{"t":68.76,"who":"nexubo","text":"还要扣成本。这里是9.79，尚未计算法币兑换、提现等可能的费用。币价涨跌并不等于最终净收益。"},{"t":95.25,"who":"narrator","text":"需要转回银行时，先查你所在地区是否支持，再按官方路径兑换或提现到符合要求的本人账户。核对姓名、到账金额、费用和预计处理条件。"},{"t":116.25,"who":"sam","text":"不是。"},{"t":116.98,"who":"nexubo","text":"保留交易和提现记录；不确定资金性质，就不要根据一个\"成功\"提示作判断。"},{"t":131.25,"who":"narrator","text":"便宜一点的网络，点错一下，币就可能找不回。下一集：转账前一个也别猜。"},{"t":137.95,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":9,"title":"转账之前，这几项一个也别猜","goal":"会核对币种、网络、地址、备注及到账条件，并先做小额测试。","task":"在故意有错的模拟提币表里纠正网络不匹配和缺失备注；再做虚拟小额测试。","answer":"所有关键条件匹配才可提交；没有\"自动改成正确网络\"的默认保护。","takeaways":["转账前先确认接收方支持的币种和网络。","从接收页面复制地址，完整核对，需要时填写 Memo／Tag。","先小额测试，确认到账后再转大额。"],"quiz":{"q":"接收页面要求填写 Memo，你该怎么做？","options":["不用管，有地址就够了","按页面显示准确填写 Memo","用上次转账的 Memo"],"answer":1,"why":"需要 Memo 或 Tag 时不填，转账可能无法入账。"},"transcript":[{"t":0.25,"who":"sam","text":"这个网络更便宜，随便换它不就好了？"},{"t":9.25,"who":"nexubo","text":"先确认收款方支持哪种资产和网络，再选择费用。两端不匹配，不能因为便宜就发送。同叫泰达币，也可能在不同网络上。"},{"t":39.25,"who":"narrator","text":"你可以暂时把网络想成路线，把地址想成目的地，但地址看起来一样，也不代表网络兼容。必须查看接收平台对这条链和这项资产的支持。"},{"t":75.25,"who":"nexubo","text":"从收款页面复制地址，再核对完整内容。若要求备注或标签，也要填写。确认最低充值、提币费用和到账金额；不要只靠地址前后几个字符判断。"},{"t":106.25,"who":"narrator","text":"先做一笔满足最低条件的小额测试，并确认接收方实际入账。后续大额仍要重新核对，不能盲目复用历史记录。自托管转账还要准备相应网络手续费。"},{"t":130.25,"who":"sam","text":"不能。"},{"t":131.16,"who":"nexubo","text":"转账前多核对一次，比转错后找人补救更重要。"},{"t":146.25,"who":"narrator","text":"显示成功却没到账？先别再转。下一集：该查哪里。"},{"t":151.65,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":10,"title":"显示成功却没到账，该查哪里？","goal":"能区分发送方处理、链上确认和平台入账，知道有限补救路径。","task":"将三个故障场景匹配到发送方、链上状态和接收方。","answer":"定位状态再找相应官方渠道；未知原因不重复付款。","takeaways":["已提交、已上链、已到账，是三个不同的站点。","拿交易哈希到对应网络的区块浏览器查询。","只向官方客服提供记录，绝不给助记词、私钥或验证码。"],"quiz":{"q":"转账显示“已发送”却没到账，第一步做什么？","options":["再发一次同样的金额","用记录和交易哈希查清卡在哪一站","付钱给承诺能找回的人"],"answer":1,"why":"先找到卡住的环节，再联系对应的官方渠道，不要继续发送。"},"transcript":[{"t":0.25,"who":"sam","text":"没到账，我再转几笔试试？"},{"t":9.25,"who":"nexubo","text":"先别重复转。已提交、已上链、已入账不是一回事。先确认卡在哪一站，再决定该联系谁。"},{"t":32.25,"who":"narrator","text":"保存发送记录。若有交易哈希，在对应网络的正规区块浏览器查看状态、目标地址和数量；不要把另一条链的查询结果混进来。"},{"t":60.25,"who":"nexubo","text":"接收平台可能还需要确认数或内部审核。若币种、网络、地址或备注填错，先停止继续转账，提交事实资料给官方客服。"},{"t":84.25,"who":"narrator","text":"通常不能像撤销普通操作一样撤回已完成的链上转账。是否能找回，要看技术和平台条件，不能保证；别相信付钱就必定找回。"},{"t":103.25,"who":"sam","text":"提供必要交易记录，不提供助记词、私钥和验证码。"},{"t":107.92,"who":"nexubo","text":"对，先定位，不盲目补转。"},{"t":116.25,"who":"narrator","text":"\"我是客服，把恢复词发给我。\"下一集：骗子到底要什么。"},{"t":122.45,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":11,"title":"别人说能帮你赚钱，先看他要什么","goal":"识别秘密凭证索取、私下付款、异常授权和保本承诺。","task":"识别四段虚构聊天的危险请求，选择停止和官方核验路径。","answer":"任何人索取私钥、恢复词、验证码或不明授权，都不应照做。","takeaways":["助记词和私钥是控制权，不是客服验证码。","保证收益、催你付款，都是危险信号。","看不懂的签名或授权，一律不要确认。"],"quiz":{"q":"为了收款，下面哪一项可以安全地告诉对方？","options":["你的公开收款地址","你的助记词","一次性验证码"],"answer":0,"why":"公开地址就是用来收款的。秘密和验证码会把控制权交出去。"},"transcript":[{"t":0.25,"who":"sam","text":"他说自己是客服，要帮我升级钱包。"},{"t":9.25,"who":"nexubo","text":"普通助记词钱包的恢复词是控制凭证，不是客服验证码。私钥也一样。不要发给任何人，学院问答助手同样不该索取。"},{"t":32.25,"who":"narrator","text":"还有两类危险信号：保证收益、催促付款。高收益截图不能证明真实，也不说明你能复现。有人催你越过正常核对步骤，就先停下来。"},{"t":60.25,"who":"nexubo","text":"连接钱包、签署消息和授权资产，不是同一件事。看不懂签名或授权，就不确认；不要以为没有输入密码就一定没有风险。"},{"t":84.25,"who":"narrator","text":"怀疑泄露时，停止继续操作，使用官方安全渠道处理；根据泄露内容采取针对措施，不要在骗子指挥下下载远程控制软件。"},{"t":103.25,"who":"sam","text":"能公开接收信息，不等于能交出控制凭证。"},{"t":106.72,"who":"nexubo","text":"不交秘密、不乱授权、不被催着付款。"},{"t":116.25,"who":"narrator","text":"看完十一集，是不是该充值了？第1季结课，答案可能出乎你意料。"},{"t":123.15,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":12,"title":"第一部分小结：你能完成，也能选择不做","goal":"独立完成模拟现货与转账判断，并把操作正确和盈利分开。","task":"依次完成模拟买卖、费用核对、错误网络拒绝和诈骗识别；关键题必须全对。","answer":"按正确流程完成或主动停止不合适操作均可过关；不按盈利评分。","takeaways":["目标是流程正确：入口与资格、现货、金额与手续费、再看记录。","看不清的转账主动停下，也是正确答案。","你得到的是学习记录，不是投资许可证。"],"quiz":{"q":"练习转账显示网络不对，正确做法是？","options":["先发出去碰碰运气","停下来，不发送","换成更大的金额"],"answer":1,"why":"网络、费用或身份不清楚时，停下来比硬把任务做完更重要。"},"transcript":[{"t":0.25,"who":"sam","text":"我看了十一集，是不是现在就该充值？"},{"t":9.25,"who":"nexubo","text":"学会操作，不代表必须投资。今天只用模拟资金完成一条流程：核对入口和资格，找到现货，确认金额与费用，再查看成交记录。"},{"t":39.25,"who":"narrator","text":"练习里即使价格下跌，你也可能把操作做对。我们评分看的是是否核对、是否理解，而不是你碰巧选中了上涨。"},{"t":75.25,"who":"sam","text":"这条转账信息有问题，我不转。"},{"t":78.5,"who":"nexubo","text":"这也是正确答案。遇到不确定的网络、费用或身份信息，停下比强行完成任务更重要。"},{"t":106.25,"who":"narrator","text":"最后复述三个判断：资产去了哪里，钱实际扣了多少，以及谁能控制你的账户。说不清楚的部分，就回到对应课程再练一次。"},{"t":130.25,"who":"nexubo","text":"你获得的是学习记录，不是投资资格。继续学习可以，暂时不交易也可以。先看懂，再动手。"},{"t":146.25,"who":"nexubo","text":"等你决定开始时，先在 NexuAlpha 并排对比交易所。通过官方合作链接注册并填写我们的邀请码，返还部分手续费；再加入我们的 Telegram 获取新课程。"},{"t":157.55,"who":"narrator","text":"第2季：你看到的价格，不一定是你付的价格。下一季揭晓。"},{"t":163.05,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":13,"title":"屏幕上的价格，为什么不是我的成交价？","goal":"理解订单簿、买卖价差、成交深度、手续费与滑点。","task":"在两档虚拟卖单中撮合0.002 BTC，计算加权平均价。","answer":"总额100.10，均价50,050；这是成交金额，尚未另扣教学手续费。若另收0.1%报价资产手续费：费用0.1001，总支出100.2001（不能先四舍五入再计算）。","takeaways":["最新价只是最近一笔成交，不是任意数量都能成交的报价。","订单较大时，可能吃掉订单簿里好几档价格。","滑点和手续费是两笔不同的成本：以账单为准。"],"quiz":{"q":"0.002 BTC 一半在 50,000 成交，另一半在 50,100 成交，成交均价是多少？","options":["50,000","50,050","50,100"],"answer":1,"why":"两半数量相同，均价是 50,050。手续费另计。"},"transcript":[{"t":0.25,"who":"sam","text":"刚才明明是这个价，怎么我的账单变了？"},{"t":9.25,"who":"nexubo","text":"屏幕上的最新价，是最近一笔成交的记录，不是给你无限数量的报价。现在有人愿意买多少、卖多少，要看买卖盘。"},{"t":32.25,"who":"narrator","text":"假设你买0.002枚，第一档只有一半，另一半只能在更高价位成交。两笔合起来，平均是50,050，而不是50,000。"},{"t":60.25,"who":"nexubo","text":"滑点是预期价和实际成交价的差异，不一定都是坏方向。交易费则是另一项成本；不要把它们混在一个\"免费\"口号里。"},{"t":84.25,"who":"narrator","text":"订单更大、可成交深度更少或行情变化更快时，成交结果更可能偏离预期。下单前看金额和深度，成交后看实际均价。"},{"t":103.25,"who":"sam","text":"不能。"},{"t":104.04,"who":"nexubo","text":"看到账单才算清楚成交，不只盯着最大的那个数字。"},{"t":116.25,"who":"nexubo","text":"手续费是你真正能降低的一项成本。在 NexuAlpha 对比各家费用，通过官方合作链接注册并填写我们的邀请码，可返还部分交易手续费。成本降低，风险不变。"},{"t":126.75,"who":"narrator","text":"下了买单却迟迟不成交，系统坏了吗？下一集：市价、限价和撤单。"},{"t":132.45,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":14,"title":"市价、限价、撤单，分别解决什么问题？","goal":"会根据成交优先或价格边界选择订单，并理解未成交和部分成交。","task":"放置虚拟限价单、观察部分成交，再撤销剩余数量。","answer":"价格条件合适也受可成交数量等因素影响；已成交部分不能被撤单逆转。","takeaways":["市价单按当前可成交的价格快速成交，最终价格可能变动。","限价单锁定你能接受的价格，但不保证成交。","撤单只影响未成交的部分，已成交的不会回滚。"],"quiz":{"q":"限价单成交了一半，你点了撤单，会怎样？","options":["全部撤回","只撤掉未成交的一半","已成交的一半变成市价单"],"answer":1,"why":"撤单无法倒回已成交的部分，只会停止剩余数量。"},"transcript":[{"t":0.25,"who":"sam","text":"我按了买入，为什么一直不成交？"},{"t":9.25,"who":"nexubo","text":"市价单倾向于尽快按当前可用报价成交，但最终价格可能变化。限价单规定买入不超过、卖出不低于某个价格，不保证成交。"},{"t":32.25,"who":"narrator","text":"想低于当前价格买，就可能需要等待。反过来，限价单若已经满足对手盘条件，也可能立即成交，不是每张限价单都只能排队。"},{"t":60.25,"who":"sam","text":"那撤单是不是把刚才买的也撤掉？"},{"t":62.82,"who":"nexubo","text":"不是。撤单只处理尚未成交的部分；已经成交的资产变化不会被倒放。"},{"t":84.25,"who":"narrator","text":"看清状态再操作。是否属于挂单方或吃单方，要看实际成交方式；并不是选择限价，就必定得到某一种费率。"},{"t":103.25,"who":"sam","text":"不会。"},{"t":104.12,"who":"nexubo","text":"选订单是在选择执行方式，不是在许愿。"},{"t":116.25,"who":"narrator","text":"绿色蜡烛，是不是代表下一根也会涨？下一集。"},{"t":121.05,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":15,"title":"一根K线，到底告诉你哪四件事？","goal":"读出开、高、低、收与时间周期，不把颜色或单根形态当预测。","task":"在虚拟K线上点击开、高、低、收，并确认图表周期。","answer":"50,000／51,000／49,000／50,500；周期五分钟。","takeaways":["一根 K 线记录一个周期的四个价格：开盘、最高、最低、收盘。","先看时间周期，再看形状：五分钟不是一天。","各 App 的涨跌颜色可能不同；一根 K 线是记录，不是预言。"],"quiz":{"q":"一根五分钟 K 线：开 50,000，最高 51,000，最低 49,000，收 50,500。最高价是？","options":["50,500","51,000","49,000"],"answer":1,"why":"上影线顶端就是这个周期的最高价：51,000。"},"transcript":[{"t":0.25,"who":"sam","text":"绿色，是不是表示下一秒还会涨？"},{"t":9.25,"who":"nexubo","text":"一根K线记录一个时间段的四个价格：开盘、最高、最低、收盘。这里是虚构的五分钟行情，不是未来五分钟的保证。"},{"t":32.25,"who":"narrator","text":"实体帮助你看开盘与收盘的差，影线标出期间到过的高低点。还没结束的这根线，会随着新成交继续改变。"},{"t":60.25,"who":"sam","text":"为什么切换周期，图看起来就不一样？"},{"t":63.75,"who":"nexubo","text":"每根线代表的时间长度变了。先读周期，再谈形状，不能把五分钟当成一天。"},{"t":84.25,"who":"narrator","text":"不同应用可能使用不同涨跌颜色，所以要看图例和数字。历史走势可以提供信息，但单根K线不能保证下一步涨跌。"},{"t":103.25,"who":"sam","text":"最高51,000，收盘50,500。"},{"t":108.91,"who":"nexubo","text":"先读记录，别把记录当预言。"},{"t":116.25,"who":"narrator","text":"\"我有1,000，只想亏20，那就全买进去？\"下一集：先想能亏多少。"},{"t":122.35,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":16,"title":"先想能亏多少，再决定买多少","goal":"理解账户资金、仓位金额和计划风险不是同一个数字。","task":"根据给定入场、止损距离和教学风险预算，算出虚拟仓位。","answer":"400 USDT名义现货金额；0.008 BTC；费用和执行偏差需另计。","takeaways":["账户余额、仓位大小、计划风险，是三个不同的数字。","先定好离场点，再决定仓位大小。","离场距离 5%、风险预算 20，仓位约为 400。"],"quiz":{"q":"入场 50,000，计划离场 47,500，你最多接受亏 20。仓位大约多大？","options":["20","400","4,000"],"answer":1,"why":"离场点相差 5%，400 的 5% 就是 20。成本另算。"},"transcript":[{"t":0.25,"who":"sam","text":"我有1,000，只想亏20，那就先全买进去？"},{"t":9.25,"who":"nexubo","text":"账户里有多少、这一笔买多少、计划最多承担多少损失，是三件不同的事。先有退出条件，才能估算仓位。"},{"t":35.25,"who":"narrator","text":"只看一道练习题：入场50,000，计划在47,500退出，差5%。假设你计划承担20的价格损失，忽略成本时，仓位约为400。"},{"t":67.25,"who":"sam","text":"原来\"最多亏20\"，不等于\"只买20\"？"},{"t":70.55,"who":"nexubo","text":"对。这里400的仓位跌5%，才对应20；这只是教学参数。"},{"t":95.25,"who":"narrator","text":"真实行情会有滑点、跳空、费用或执行失败，所以计划风险不等于保证最多亏这么多。不要借钱来完成课程，也不要把生活必需资金当练习。"},{"t":116.25,"who":"sam","text":"二十。"},{"t":116.98,"who":"nexubo","text":"先算最坏能接受什么，再看你是否需要这笔交易。"},{"t":131.25,"who":"narrator","text":"设好了止损，就一定只亏这么多吗？下一集：止损的真相。"},{"t":137.75,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":17,"title":"止盈止损，是计划，不是保险","goal":"理解触发与成交的区别，能识别止损市价和止损限价的不同风险。","task":"对比同一段急跌中止损市价和止损限价的模拟结果。","answer":"前者可能滑点，后者可能不成交；二者都不是保本保险。","takeaways":["止损是执行离场计划，不是保险。","止损市价单离场快，但急跌时可能滑点。","止损限价单锁住价格，但可能根本卖不出去。"],"quiz":{"q":"急跌行情中，止损限价单可能发生什么？","options":["一定按触发价成交","价格冲过去时可能不成交","自动变成保险"],"answer":1,"why":"限价保护了价格，所以行情太快时订单可能一直挂着不成交。"},"transcript":[{"t":0.25,"who":"sam","text":"止损已经设好，所以一定只亏我填的金额？"},{"t":9.25,"who":"nexubo","text":"止损是条件达到时执行退出计划，不是保险。触发了条件，不等于一定按那个价格成交，也不保证损失刚好停在那里。"},{"t":32.25,"who":"narrator","text":"触发后按市价执行，重视尽快离场，但实际价格可能有滑点。行情很快或深度不足时，差异可能更大。"},{"t":60.25,"who":"nexubo","text":"触发后挂限价，能限制接受的成交价格，却可能因为价格快速穿过而卖不掉。两种方式不是谁永远更好，而是不同取舍。"},{"t":84.25,"who":"narrator","text":"设置后检查方向、数量和订单状态。合约还要核对用哪种价格触发，避免把止损线放在可能先被强平的位置。"},{"t":103.25,"who":"sam","text":"不保证。"},{"t":104.72,"who":"nexubo","text":"明白限制，才能把止损当成有效计划，而不是护身符。"},{"t":116.25,"who":"narrator","text":"都写着BTC，其中一个却可能不给你任何比特币。下一集：现货和合约。"},{"t":123.15,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":18,"title":"现货和合约，买到的不是同一件事","goal":"区分持有资产与持有价格合约，理解做多、做空的方向。","task":"将现货资产余额与合约持仓字段分别匹配到正确页面。","answer":"合约仓位不等同于可提取的基础币资产；课程不要求真实开户。","takeaways":["现货是用一种资产换另一种；永续合约是一个合约仓位。","做多盼涨，做空盼跌；方向错了，哪边都会亏。","合约是另一种风险结构，不是必须升级的关卡。"],"quiz":{"q":"合约仓位会给你可以提走的比特币吗？","options":["会，和现货一样","不会，它是按盈亏结算的合约","只有 10 倍杠杆才会"],"answer":1,"why":"U 本位永续按合约结算盈亏，不是可以提现的币。"},"transcript":[{"t":0.25,"who":"sam","text":"都写着比特币，不就是同一种买卖吗？"},{"t":9.25,"who":"nexubo","text":"没有借贷的普通现货，是用一种资产换另一种资产。这里讲的线性永续合约，则是持有按价格变化结算盈亏的合约仓位，不等于买到可提取的比特币。"},{"t":32.25,"who":"narrator","text":"做多通常希望价格上涨，做空通常希望价格下跌。判断错了方向，两边都会亏。可以做空，不代表更容易赚钱。"},{"t":60.25,"who":"sam","text":"我应该从现货升级到合约吗？"},{"t":62.38,"who":"nexubo","text":"不用。合约是另一种风险结构，不是学习必须达到的等级；知道它是什么，也可以选择不用。"},{"t":84.25,"who":"narrator","text":"不借贷的普通现货没有合约那种保证金不足强平，但资产仍可能大幅贬值。不能因为没有强平，就说它保本。"},{"t":103.25,"who":"sam","text":"不是。"},{"t":103.9,"who":"nexubo","text":"先分清交易对象，再研究杠杆。"},{"t":116.25,"who":"narrator","text":"开10倍，平台会送你900吗？下一集。"},{"t":121.25,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":19,"title":"10倍杠杆，是钱变多，还是风险变大？","goal":"分清保证金、名义仓位和收益率，理解固定仓位下杠杆设置的效果。","task":"分别选择固定保证金和固定仓位模式，观察价格变动后的金额盈亏。","answer":"固定保证金提高杠杆会扩大名义仓位；固定仓位则不自动扩大金额盈亏。","takeaways":["100 保证金控制 1,000 仓位，就是 10 倍杠杆。","价格波动作用在仓位上，盈亏由你的保证金承担。","仓位不变时，调整杠杆改变的是保证金，不是盈亏金额。"],"quiz":{"q":"1,000 的仓位反向波动 1%（不计手续费），大约亏多少？","options":["1","10","100"],"answer":1,"why":"1,000 仓位的 1% 约是 10，从你的保证金里扣。"},"transcript":[{"t":0.25,"who":"sam","text":"开十倍，平台是不是送我900？"},{"t":9.25,"who":"nexubo","text":"不是送现金。简化来说，100保证金控制1,000名义仓位，是10倍杠杆。价格变化作用在仓位上，你的保证金承担对应盈亏。"},{"t":35.25,"who":"narrator","text":"暂不计费用，价格反向1%，1,000仓位大约亏10，2,000仓位大约亏20。百分比看起来很小，对小额保证金却可能很明显。"},{"t":67.25,"who":"nexubo","text":"还有一个容易弄错的地方：如果仓位大小没变，只调整杠杆设置，同样价格变化的金额盈亏不会凭空翻倍；主要变化在保证金需求和风险缓冲。"},{"t":95.25,"who":"narrator","text":"实际强平还涉及维持保证金、标记价格与费用，不能说10倍就一定恰好跌10%才爆仓。不要靠这个近似值设置真实交易。"},{"t":116.25,"who":"sam","text":"不会。"},{"t":117.06,"who":"nexubo","text":"放大的是仓位对本金的影响，不是你的判断能力。"},{"t":131.25,"who":"narrator","text":"保证金还没归零，为什么就可能出局？下一集：那条看不见的线。"},{"t":137.05,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":20,"title":"保证金为什么还没归零，就可能出局？","goal":"区分初始保证金、维持保证金、权益与可用余额。","task":"给定初始100、浮亏20、暂不计费，填写简化权益80；识别变动字段。","answer":"权益80；维持要求需另按产品规则计算，不能固定认为等于初始保证金。","takeaways":["初始保证金用来开仓，维持保证金用来保住仓位。","权益 = 保证金加减未实现盈亏：100 亏 20，剩 80。","保证金还没归零，风控系统就可能介入。"],"quiz":{"q":"初始保证金 100，仓位亏损 20（不计费用），简化权益是多少？","options":["100","80","120"],"answer":1,"why":"100 减去亏损 20 剩 80；价格继续反向，缓冲还会继续缩小。"},"transcript":[{"t":0.25,"who":"sam","text":"还有余额，怎么就不让我继续等？"},{"t":9.25,"who":"nexubo","text":"开仓时需要初始保证金；持仓期间，还必须满足维持保证金要求。初始放了多少，不等于之后一直有多少风险缓冲。"},{"t":35.25,"who":"narrator","text":"假设初始保证金是100，仓位浮亏20，忽略其他项目，相关权益就只剩80。价格继续不利变化，可用缓冲也会继续缩小。"},{"t":67.25,"who":"nexubo","text":"当权益接近平台要求的维持水平，风险系统就可能介入；不一定等到全部归零。具体看哪种账户、保证金模式和产品规则。"},{"t":95.25,"who":"sam","text":"那我一直补钱就安全了？"},{"t":99.06,"who":"nexubo","text":"补钱不改变价格方向，也不保证不会被强平。它可能把更多资金带入同一笔风险。"},{"t":116.25,"who":"sam","text":"不是，一个关乎开仓条件，一个关乎持仓维持要求。"},{"t":121.2,"who":"nexubo","text":"先看权益，再看它离警戒线多远。"},{"t":131.25,"who":"narrator","text":"把100装进小盒子，另外900就永远安全吗？下一集：逐仓。"},{"t":137.95,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":21,"title":"逐仓：把这笔交易装进独立小盒子","goal":"理解单仓保证金隔离及追加保证金可能扩大风险资金。","task":"在模拟设置中找出自动追加开关，并解释它为何改变参与承担风险的资金。","answer":"自动或手动追加会增加投入的保证金；不能无条件承诺只损失初始金额。","takeaways":["逐仓让一个仓位拥有自己独立的保证金。","分配的保证金仍然可能亏光；逐仓不是止损单。","自动追加或手动追加，会让更多资金承担同一个风险。"],"quiz":{"q":"你给逐仓仓位打开了自动追加保证金，会发生什么？","options":["不变，亏损仍只限于最初的 100","更多可用余额可能流入这个仓位","仓位变得没有风险"],"answer":1,"why":"自动追加会把可用余额转入仓位，承担风险的资金就变多了。"},"transcript":[{"t":0.25,"who":"sam","text":"放100做逐仓，另外900就永远碰不到了？"},{"t":9.25,"who":"nexubo","text":"逐仓的核心，是给仓位单独分配保证金。在不追加、不启用自动追加等简化条件下，这个仓位的强平风险主要由分配的保证金承担。"},{"t":32.25,"who":"narrator","text":"所以它便于区分不同仓位的保证金范围。但这100本身仍可能损失，逐仓不是让亏损消失，也不是止损订单。"},{"t":60.25,"who":"nexubo","text":"注意这个开关：有的平台提供自动追加保证金。打开后，可用余额可能继续流入仓位。手动追加也一样，会让更多资金参与承担风险。"},{"t":84.25,"who":"narrator","text":"别只看\"逐仓\"两个字就假定最大损失永远等于最初那100。具体还要核对追加设置、费用和产品规则。"},{"t":103.25,"who":"sam","text":"不能。"},{"t":103.99,"who":"nexubo","text":"逐仓看隔离范围，也要看有没有额外接进来的管道。"},{"t":116.25,"who":"narrator","text":"一个仓位漏水，另一个也开始下沉。下一集：全仓。"},{"t":121.15,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":22,"title":"全仓：为什么一笔亏损会影响别的仓位？","goal":"理解同一保证金池的共享风险，不把全仓解释为所有个人资产。","task":"让一个虚拟仓位亏损，观察同池风险变化，并圈出不在该保证金池内的资产。","answer":"风险可扩展到同一保证金池；不自动覆盖所有个人资产。","takeaways":["全仓让多个仓位共用一个保证金池。","一个仓位亏损，会吃掉其他仓位依赖的缓冲。","它不会动用你的银行卡或个人钱包。"],"quiz":{"q":"全仓就一定更安全吗？","options":["是，永远不会被强平","不一定，取决于共享资金池和规则","是，它会用上你所有银行卡"],"answer":1,"why":"额外保证金能推迟风控处理，但也让更多资金承担亏损。"},"transcript":[{"t":0.25,"who":"sam","text":"亏的是左边这笔，右边怎么也变危险了？"},{"t":9.25,"who":"nexubo","text":"全仓会在规则允许的范围内共享保证金支持仓位。这里假设同一保证金池里有1,000，多个仓位都可能依赖它，不是只盯各自最初分了多少。"},{"t":39.25,"who":"narrator","text":"一个仓位亏损，可能消耗其他仓位依赖的风险缓冲。盈利、亏损、挂单占用和抵押品价值，都可能影响同一个账户的风险状态。"},{"t":75.25,"who":"sam","text":"那全仓是不是更不容易爆仓，所以更安全？"},{"t":79.67,"who":"nexubo","text":"额外资金可能延后某个仓位触发风险处置，但也让更大范围的资金参与承担损失。"},{"t":106.25,"who":"narrator","text":"全仓不是平台能自动动用你所有银行卡或个人钱包。具体包括哪些账户和抵押资产，要按产品规则核对；复杂抵押组合可能还有折扣与自身价格风险。"},{"t":130.25,"who":"sam","text":"不一定，要看共享池和账户规则。"},{"t":135.19,"who":"nexubo","text":"看整池资金，不要只看一个仓位框。"},{"t":146.25,"who":"narrator","text":"你盯的价格还没到，警报却响了。下一集：谁按下了强平按钮。"},{"t":152.55,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":23,"title":"爆仓：谁按下了强制平仓按钮？","goal":"理解强平触发、标记价格与维持要求，不使用倒数杠杆当准确公式。","task":"播放同一段先跌后涨的虚拟行情，分别观察普通现货和简化逐仓合约。","answer":"路径风险重要；合约中途强平后不会因后续反弹自动恢复仓位。","takeaways":["很多永续合约按标记价格和保证金规则判断强平，而不是最新成交价。","接近维持保证金时，系统可能减仓或强制平仓。","仓位被平掉后，价格反弹也回不来。"],"quiz":{"q":"杠杆仓位被强平后，价格又涨回来了，会怎样？","options":["仓位自动恢复","仓位仍然是平掉的，路径很重要","交易所退还亏损"],"answer":1,"why":"仓位一旦被强制平仓就没了，之后的反弹只对仍在持有的人有用。"},"transcript":[{"t":0.25,"who":"sam","text":"我看的价格还没到，为什么已经报警了？"},{"t":9.25,"who":"nexubo","text":"最新成交价不一定是强平判断采用的价格。许多永续产品会依据标记价格及保证金规则评估风险；你要看平台真正采用哪套规则。"},{"t":35.25,"who":"narrator","text":"价格对仓位不利时，损失侵蚀权益。接近维持要求后，系统可能先撤销挂单、减仓或进行强制平仓，不会等你同意才一定行动。"},{"t":67.25,"who":"nexubo","text":"爆仓通常指这种强制平仓风险事件，不是简单的手机按钮失灵。实际触发还受到费用、维持保证金、仓位模式等影响，不是10倍一定正好跌10%。"},{"t":95.25,"who":"sam","text":"后来涨回来了，我还能等回来吗？"},{"t":99.46,"who":"nexubo","text":"已经关闭的仓位不会自动恢复。先下跌再上涨，对杠杆仓位和一直持有普通现货，可能是不同结果。"},{"t":116.25,"who":"sam","text":"不保证。"},{"t":117.73,"who":"nexubo","text":"不仅看终点，还要看沿途能不能承受。"},{"t":131.25,"who":"narrator","text":"价格没怎么动、也没平仓，余额却少了。下一集：最后一关。"},{"t":137.35,"who":"narrator","text":"先看懂，再动手。"}]},{"ep":24,"title":"没涨没跌也扣钱？带着成本完成最后一关","goal":"知道资金费率的方向与计费基数，综合核对合约风险并能选择不交易。","task":"计算单期费用0.10，并完成虚拟合约订单核对；不得调用真实下单接口。","answer":"正费率多付空收；本例费用0.10；风险关键题全部答对或明确选择不交易。","takeaways":["资金费在多空之间支付，不是固定交给交易所的费用。","它按仓位价值计算：1,000 乘以 0.01% 就是 0.10。","选择不交易，也是合格的答案。"],"quiz":{"q":"资金费率为正时，通常谁付钱？","options":["空头付给多头","多头付给空头","所有人付给交易所"],"answer":1,"why":"费率为正时，多头通常向空头支付；为负时方向相反。"},"transcript":[{"t":0.25,"who":"sam","text":"价格没怎么动，我也没平仓，为什么余额少了？"},{"t":9.25,"who":"nexubo","text":"永续合约除了交易费用，通常还有资金费用机制。正费率时，通常多头支付给空头；负费率时方向相反。它不是每个人都支付给交易所的一笔固定利息。"},{"t":42.25,"who":"narrator","text":"假设结算时仓位价值是1,000，费率是0.01%，本次费用是0.10；按仓位价值计算，不是按最初的100保证金算。"},{"t":83.25,"who":"nexubo","text":"结算间隔和费率可能因交易对、平台和市场情况变化。不能记成所有合约永远每八小时扣一次，也不能把收资金费当作无风险收益。"},{"t":117.25,"who":"narrator","text":"最后一关只做模拟。先解释交易对象和方向，再核对模式、仓位、保证金、自动追加、退出计划与成本。看不懂一项，就暂停，不靠猜按钮完成。"},{"t":144.25,"who":"sam","text":"我知道怎么操作，也知道这笔风险不适合我，所以不做。"},{"t":149.09,"who":"nexubo","text":"这也是合格的学习结果。完成课程，不代表盈利能力；先看懂，再动手。"},{"t":161.25,"who":"nexubo","text":"无论交易什么，手续费都会累积成成本。在 NexuAlpha 对比各家费用，通过官方合作链接注册并填写我们的邀请码，可返还部分手续费。成本降低，风险不变。"},{"t":172.75,"who":"narrator","text":"两季都学完了。挑一集你觉得最难的，在任何真实交易前再看一遍。"},{"t":178.65,"who":"narrator","text":"先看懂，再动手。"}]}]});
